            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nQ = chr(39)\nconn.execute("CREATE TABLE ledger(id INTEGER PRIMARY KEY, status TEXT DEFAULT " + Q + "open" + Q + ", balance REAL DEFAULT 0, created TEXT DEFAULT " + Q + "2026-01-01" + Q + ")")\nconn.execute("INSERT INTO ledger(id) VALUES(1)")\nconn.execute("INSERT INTO ledger VALUES(2, ?, ?, ?)", ("shut", 5.0, "2026-02-02"))\nrows = conn.execute("SELECT id, status, balance, created FROM ledger ORDER BY id").fetchall()\nprint(("PASS" if rows[0] == (1, "open", 0.0, "2026-01-01") else "FAIL") + f": defaults applied -> {rows[0]}")\nassert rows[0] == (1, "open", 0.0, "2026-01-01")\nprint(("PASS" if rows[1] == (2, "shut", 5.0, "2026-02-02") else "FAIL") + ": explicit wins")\nassert rows[1] == (2, "shut", 5.0, "2026-02-02")\nconn.close()',
