            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE items(id INTEGER PRIMARY KEY, name TEXT)")\nconn.execute("CREATE TABLE item_tags(item_id INTEGER REFERENCES items(id), tag TEXT)")\nconn.executemany("INSERT INTO items VALUES(?, ?)", [(1, "shirt"), (2, "hat")])\nconn.executemany("INSERT INTO item_tags VALUES(?, ?)", [(1, "red"), (1, "sale"), (2, "blue")])\nblue = conn.execute("SELECT i.name FROM items i JOIN item_tags t ON t.item_id = i.id WHERE t.tag = ?", ("blue",)).fetchall()\nprint(("PASS" if blue == [("hat",)] else "FAIL") + f": tagged query -> {blue}")\nassert blue == [("hat",)]\nsale = conn.execute("SELECT COUNT(*) FROM item_tags WHERE tag = ?", ("sale",)).fetchone()[0]\nprint(("PASS" if sale == 1 else "FAIL") + ": per-tag count exact")\nassert sale == 1\nconn.close()',
