            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT)")\nconn.execute("CREATE TABLE orders(id INTEGER PRIMARY KEY, customer_id INTEGER, total REAL)")\nconn.executemany("INSERT INTO customers VALUES(?, ?)", [(1, "ada"), (2, "bob"), (3, "cy")])\nconn.executemany("INSERT INTO orders VALUES(?, ?, ?)", [(10, 1, 50.0), (11, 1, 20.0)])\nrows = conn.execute("SELECT c.name, SUM(o.total) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.id ORDER BY c.name").fetchall()\nprint(("PASS" if rows == [("ada", 70.0), ("bob", None), ("cy", None)] else "FAIL") + f": coverage -> {rows}")\nassert rows == [("ada", 70.0), ("bob", None), ("cy", None)]\nconn.close()',
