            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE sizes(s TEXT)")\nconn.execute("CREATE TABLE colors(c TEXT)")\nconn.executemany("INSERT INTO sizes VALUES(?)", [("S",), ("M",), ("L",)])\nconn.executemany("INSERT INTO colors VALUES(?)", [("red",), ("blue",)])\nvariants = conn.execute("SELECT s, c FROM sizes CROSS JOIN colors ORDER BY s, c").fetchall()\nprint(("PASS" if len(variants) == 6 and variants[0] == ("L", "blue") else "FAIL") + f": variants -> {len(variants)}")\nassert len(variants) == 6 and variants[0] == ("L", "blue")\nprint("PASS: 3 x 2 counted exactly")\nconn.close()',
