            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE customers(id INTEGER PRIMARY KEY, name TEXT)")\nconn.execute("CREATE TABLE orders(id INTEGER PRIMARY KEY, customer_id INTEGER, total REAL)")\nconn.executemany("INSERT INTO customers VALUES(?, ?)", [(1, "ada"), (2, "bob")])\nconn.executemany("INSERT INTO orders VALUES(?, ?, ?)", [(10, 1, 50.0), (11, 1, 20.0)])\nrows = conn.execute("SELECT name, (SELECT COUNT(*) FROM orders WHERE customer_id = customers.id) AS n, COALESCE((SELECT SUM(total) FROM orders WHERE customer_id = customers.id), 0) AS t FROM customers ORDER BY name").fetchall()\nprint(("PASS" if rows == [("ada", 2, 70.0), ("bob", 0, 0)] else "FAIL") + f": per-customer -> {rows}")\nassert rows == [("ada", 2, 70.0), ("bob", 0, 0)]\nconn.close()',
