            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE users(name TEXT, age INTEGER)")\nconn.executemany("INSERT INTO users VALUES(?, ?)", [("ada", 36), ("bob", 12)])\nq = conn.execute("SELECT name FROM users WHERE age >= ? AND name != ?", (18, "bob")).fetchall()\nn = conn.execute("SELECT name FROM users WHERE age >= :min AND name != :other", {"min": 18, "other": "bob"}).fetchall()\nprint(("PASS" if q == n == [("ada",)] else "FAIL") + f": both styles -> {q}")\nassert q == n == [("ada",)]\nevil = "x OR 1=1 --"\nsafe = conn.execute("SELECT COUNT(*) FROM users WHERE name = ?", (evil,)).fetchone()[0]\nprint(("PASS" if safe == 0 else "FAIL") + ": injection neutralized")\nassert safe == 0\nconn.close()',
