            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE accounts(id INTEGER PRIMARY KEY, bal REAL CHECK(bal >= 0))")\nconn.execute("CREATE TABLE audit(id INTEGER PRIMARY KEY, msg TEXT)")\nconn.executemany("INSERT INTO accounts VALUES(?, ?)", [(1, 100.0), (2, 50.0)])\nconn.commit()\ntry:\n    conn.execute("UPDATE accounts SET bal = bal - 200 WHERE id = 1")\n    conn.execute("INSERT INTO audit VALUES(1, ?)", ("moved",))\n    conn.commit()\nexcept sqlite3.IntegrityError:\n    conn.rollback()\n    print("PASS: overdraft aborted the unit")\nconn.execute("UPDATE accounts SET bal = bal - 30 WHERE id = 1")\nconn.execute("UPDATE accounts SET bal = bal + 30 WHERE id = 2")\nconn.execute("INSERT INTO audit VALUES(1, ?)", ("moved 30",))\nconn.commit()\nrows = conn.execute("SELECT id, bal FROM accounts ORDER BY id").fetchall()\ntotal = conn.execute("SELECT SUM(bal) FROM accounts").fetchone()[0]\nprint(("PASS" if rows == [(1, 70.0), (2, 80.0)] and total == 150.0 else "FAIL") + f": books balance -> {rows} total={total}")\nassert rows == [(1, 70.0), (2, 80.0)] and total == 150.0\nconn.close()',
