            "Plan assertions prove access paths deterministically where timings flake; assert SEARCH in tests and measure wall time only in benchmarks.",
            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE users(id INTEGER PRIMARY KEY, email TEXT)")\nconn.executemany("INSERT INTO users VALUES(?, ?)", [(i, f"u{i}@x.io") for i in range(100)])\nbefore = conn.execute("EXPLAIN QUERY PLAN SELECT * FROM users WHERE email = ?", ("u42@x.io",)).fetchall()\nprint(("PASS" if any("SCAN" in str(r) for r in before) else "FAIL") + f": unindexed scans -> {before[0]}")\nassert any("SCAN" in str(r) for r in before)\nconn.execute("CREATE INDEX idx_users_email ON users(email)")\nafter = conn.execute("EXPLAIN QUERY PLAN SELECT * FROM users WHERE email = ?", ("u42@x.io",)).fetchall()\nprint(("PASS" if any("SEARCH" in str(r) for r in after) else "FAIL") + f": indexed seeks -> {after[0]}")\nassert any("SEARCH" in str(r) for r in after)\ngot = conn.execute("SELECT id FROM users WHERE email = ?", ("u42@x.io",)).fetchone()[0]\nprint(("PASS" if got == 42 else "FAIL") + ": same answer, better path")\nassert got == 42\nconn.close()',
            "nonexistent email must still SEARCH (plan) and return empty",
