            "Composite order follows query shape, not table shape; one composite rarely serves two different filters — design per hot query, not per table.",
            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE u(name TEXT, city TEXT, age INTEGER)")\nconn.executemany("INSERT INTO u VALUES(?, ?, ?)", [(f"n{i}", "berlin" if i % 2 else "paris", 20 + i) for i in range(200)])\nconn.execute("CREATE INDEX idx_city_age ON u(city, age)")\nplan = conn.execute("EXPLAIN QUERY PLAN SELECT * FROM u WHERE city = ? AND age BETWEEN ? AND ?", ("berlin", 30, 60)).fetchall()\nprint(("PASS" if any("SEARCH" in str(r) for r in plan) else "FAIL") + f": composite seeks -> {plan[0]}")\nassert any("SEARCH" in str(r) for r in plan)\nrows = conn.execute("SELECT COUNT(*) FROM u WHERE city = ? AND age BETWEEN ? AND ?", ("berlin", 30, 60)).fetchone()[0]\nprint(("PASS" if rows == 15 else "FAIL") + f": exact count -> {rows}")\nassert rows == 15\nconn.close()',
