            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE u(id INTEGER PRIMARY KEY, city TEXT, name TEXT)")\nconn.executemany("INSERT INTO u VALUES(?, ?, ?)", [(i, "berlin" if i % 2 else "paris", f"n{i}") for i in range(100)])\nconn.execute("CREATE INDEX idx_cov ON u(city, name)")\nplan = conn.execute("EXPLAIN QUERY PLAN SELECT name FROM u WHERE city = ?", ("berlin",)).fetchall()\nprint(("PASS" if any("COVERING INDEX" in str(r) for r in plan) else "FAIL") + f": covered -> {plan[0]}")\nassert any("COVERING INDEX" in str(r) for r in plan)\nn = conn.execute("SELECT COUNT(*) FROM u WHERE city = ?", ("berlin",)).fetchone()[0]\nprint(("PASS" if n == 50 else "FAIL") + f": exact -> {n}")\nassert n == 50\nconn.close()',
