            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE u(name TEXT)")\nconn.executemany("INSERT INTO u VALUES(?)", [(f"user{i:03d}",) for i in range(500)])\nconn.execute("CREATE INDEX idx_name ON u(name)")\npre = conn.execute("EXPLAIN QUERY PLAN SELECT * FROM u WHERE name GLOB ?", ("user1*",)).fetchall()\ncon = conn.execute("EXPLAIN QUERY PLAN SELECT * FROM u WHERE name GLOB ?", ("*ser1*",)).fetchall()\nprint(("PASS" if any("SEARCH" in str(r) for r in pre) else "FAIL") + f": prefix seeks -> {pre[0]}")\nassert any("SEARCH" in str(r) for r in pre)\nprint(("PASS" if any("SCAN" in str(r) for r in con) else "FAIL") + f": contains scans -> {con[0]}")\nassert any("SCAN" in str(r) for r in con)\nn = conn.execute("SELECT COUNT(*) FROM u WHERE name GLOB ?", ("user1*",)).fetchone()[0]\nprint(("PASS" if n == 100 else "FAIL") + f": prefix exact -> {n}")\nassert n == 100\nconn.close()',
