            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE u(city TEXT)")\nconn.executemany("INSERT INTO u VALUES(?)", [("berlin",)] * 900 + [("paris",)] * 100)\nconn.execute("CREATE INDEX idx_city ON u(city)")\nconn.execute("ANALYZE")\nstat = conn.execute("SELECT COUNT(*) FROM sqlite_stat1 WHERE tbl = ?", ("u",)).fetchone()[0]\nprint(("PASS" if stat >= 1 else "FAIL") + f": stats recorded -> {stat}")\nassert stat >= 1\nplan = conn.execute("EXPLAIN QUERY PLAN SELECT * FROM u WHERE city = ?", ("paris",)).fetchall()\nprint(("PASS" if any("SEARCH" in str(r) for r in plan) else "FAIL") + f": stats guide -> {plan[0]}")\nassert any("SEARCH" in str(r) for r in plan)\nrare = conn.execute("SELECT COUNT(*) FROM u WHERE city = ?", ("paris",)).fetchone()[0]\nprint(("PASS" if rare == 100 else "FAIL") + ": skew exact")\nassert rare == 100\nconn.close()',
