            'import sqlite3\n\nconn = sqlite3.connect(":memory:")\nconn.execute("CREATE TABLE migrations(id INTEGER PRIMARY KEY, name TEXT, applied_at TEXT)")\nSTEPS = [(1, "users"), (2, "orders")] \nfor num, name in STEPS:\n    done = conn.execute("SELECT COUNT(*) FROM migrations WHERE id = ?", (num,)).fetchone()[0]\n    if not done:\n        conn.execute("CREATE TABLE IF NOT EXISTS t{}(id INTEGER PRIMARY KEY)".format(num))\n        conn.execute("INSERT INTO migrations VALUES(?, ?, ?)", (num, name, "2026-01-01"))\nlog = conn.execute("SELECT id, name FROM migrations ORDER BY id").fetchall()\nprint(("PASS" if log == [(1, "users"), (2, "orders")] else "FAIL") + f": receipts -> {log}")\nassert log == [(1, "users"), (2, "orders")]\nagain = conn.execute("SELECT COUNT(*) FROM migrations").fetchone()[0]\nprint(("PASS" if again == 2 else "FAIL") + ": rerun writes nothing new")\nassert again == 2\nconn.close()',
            "failed step must leave no receipt (receipts only on success)",
