from app.domain_engine import DomainPack, collect_pack

DATABASE_OPS_PACK = DomainPack(
    slug="database-ops",
    domain=DOMAIN,
    career=CAREER,
    foundation=FOUNDATION,
    phases=[*PHASES_P1, *PHASES_P2, *PHASES_P3, *PHASES_P4, *PHASES_P5, *PHASES_P6, *PHASES_P7],
)

OWNED_DAYS = frozenset(list(range(1, 15)) + list(range(75, 180)))


def collect() -> list:
    """All 119 owned days as (day_number, phase, built lesson)."""
    items = collect_pack(DATABASE_OPS_PACK)
    days = sorted(d for d, _, _ in items)
    assert days == sorted(OWNED_DAYS), f"day mismatch: {len(days)} days"
    assert len(items) == 119, f"expected 119, got {len(items)}"
    return items







